BEGIN;
CREATE FUNCTION public.agentpass_reserve_maintenance_effect(p_job uuid,p_org uuid,p_kind text,p_key text,p_digest bytea) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER VOLATILE SET search_path=pg_catalog,public AS $$ DECLARE eid uuid; BEGIN IF NOT EXISTS (SELECT 1 FROM public.maintenance_jobs j WHERE j.job_id=p_job AND j.organization_id=p_org AND j.status IN ('reserved','running')) THEN RAISE EXCEPTION USING ERRCODE='insufficient_privilege',MESSAGE='maintenance job binding is invalid'; END IF; INSERT INTO public.maintenance_effects(job_id,organization_id,effect_kind,idempotency_key,request_digest) VALUES(p_job,p_org,p_kind,p_key,p_digest) ON CONFLICT(job_id,effect_kind,idempotency_key) DO UPDATE SET request_digest=EXCLUDED.request_digest RETURNING effect_id INTO eid; RETURN eid; END $$;
CREATE FUNCTION public.agentpass_cancel_maintenance_effect(p_effect uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER VOLATILE SET search_path=pg_catalog,public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.maintenance_effects e JOIN public.maintenance_jobs j ON j.job_id=e.job_id AND j.organization_id=e.organization_id WHERE e.effect_id=p_effect AND j.status IN ('reserved','running')) THEN RAISE EXCEPTION USING ERRCODE='insufficient_privilege',MESSAGE='maintenance effect binding is invalid'; END IF; UPDATE public.maintenance_effects SET state='cancelled' WHERE effect_id=p_effect AND state='reserved'; END $$;
CREATE FUNCTION public.agentpass_complete_maintenance_effect(p_effect uuid,p_response_digest bytea) RETURNS void LANGUAGE plpgsql SECURITY DEFINER VOLATILE SET search_path=pg_catalog,public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.maintenance_effects e JOIN public.maintenance_jobs j ON j.job_id=e.job_id AND j.organization_id=e.organization_id WHERE e.effect_id=p_effect AND j.status IN ('reserved','running')) THEN RAISE EXCEPTION USING ERRCODE='insufficient_privilege',MESSAGE='maintenance effect binding is invalid'; END IF; UPDATE public.maintenance_effects SET state='completed',response_digest=p_response_digest,completed_at=clock_timestamp() WHERE effect_id=p_effect AND state IN ('reserved','started','accepted'); END $$;
CREATE FUNCTION public.agentpass_reconcile_maintenance_effect(p_effect uuid,p_state text,p_response_digest bytea) RETURNS void LANGUAGE plpgsql SECURITY DEFINER VOLATILE SET search_path=pg_catalog,public AS $$ BEGIN IF p_state NOT IN ('completed','cancelled','uncertain','failed') THEN RAISE EXCEPTION USING ERRCODE='invalid_parameter_value'; END IF; IF NOT EXISTS (SELECT 1 FROM public.maintenance_effects e JOIN public.maintenance_jobs j ON j.job_id=e.job_id AND j.organization_id=e.organization_id WHERE e.effect_id=p_effect AND j.status IN ('reserved','running','uncertain')) THEN RAISE EXCEPTION USING ERRCODE='insufficient_privilege',MESSAGE='maintenance effect binding is invalid'; END IF; UPDATE public.maintenance_effects SET state=p_state,response_digest=COALESCE(p_response_digest,response_digest),completed_at=CASE WHEN p_state IN ('completed','cancelled','failed') THEN clock_timestamp() ELSE completed_at END WHERE effect_id=p_effect AND state IN ('reserved','started','accepted','uncertain'); END $$;
ALTER FUNCTION public.agentpass_reserve_maintenance_effect(uuid,uuid,text,text,bytea) OWNER TO agentpass_migrator; ALTER FUNCTION public.agentpass_cancel_maintenance_effect(uuid) OWNER TO agentpass_migrator; ALTER FUNCTION public.agentpass_complete_maintenance_effect(uuid,bytea) OWNER TO agentpass_migrator; ALTER FUNCTION public.agentpass_reconcile_maintenance_effect(uuid,text,bytea) OWNER TO agentpass_migrator;
REVOKE ALL ON FUNCTION public.agentpass_reserve_maintenance_effect(uuid,uuid,text,text,bytea),public.agentpass_cancel_maintenance_effect(uuid),public.agentpass_complete_maintenance_effect(uuid,bytea),public.agentpass_reconcile_maintenance_effect(uuid,text,bytea) FROM PUBLIC,agentpass_app,agentpass_signer,agentpass_backup,agentpass_maintenance; GRANT EXECUTE ON FUNCTION public.agentpass_reserve_maintenance_effect(uuid,uuid,text,text,bytea),public.agentpass_cancel_maintenance_effect(uuid),public.agentpass_complete_maintenance_effect(uuid,bytea),public.agentpass_reconcile_maintenance_effect(uuid,text,bytea) TO agentpass_maintenance;
COMMIT;
